export function createRepositoryLifecycleStore(database, options = {}) {
    const name = options.connection;
    const names = options.collections ?? LIFECYCLE_COLLECTIONS;
    // A transaction opened on a transaction connection is a savepoint of it,
    // whose afterCommit callbacks wait for the outermost commit.
    const nest = async (within, work) => {
        const connection = await joinable(within, database.connection(name));
        return connection.transaction((transaction) => {
            const inner = new RepositoryLifecycleStore(names, (collection) => transaction.repository(collection), (nested) => nested(inner), nest, transaction);
            return work(inner);
        });
    };
    return new RepositoryLifecycleStore(names, (collection) => database.repository(collection, name), (work) => database.transaction((connection) => {
        const inner = new RepositoryLifecycleStore(names, (collection) => connection.repository(collection), (nested) => nested(inner), nest, connection);
        return work(inner);
    }, name), nest);
}

