export class ServiceProviderRegistry {
    providers = [];
    phase = 'new';
    shutdownPromise;
    add(provider) {
        if (this.phase !== 'new') {
            throw new Error('Providers can only be added before registration.');
        }
        if (this.providers.some(({ provider: item }) => item.name === provider.name)) {
            throw new Error(`Service provider "${provider.name}" is already registered.`);
        }
        this.providers.push({ provider, state: 'new' });
    }
    registerAll() {
        this.assertPhase('new');
        for (const entry of this.providers) {
            entry.state = 'registering';
            try {
                entry.provider.register();
                entry.state = 'registered';
            }
            catch (error) {
                entry.state = 'failed';
                this.phase = 'failed';
                throw error;
            }
        }
        this.phase = 'registered';
    }
    async bootAll() {
        this.assertPhase('registered');
        await this.runPhase('booting', 'booted', (provider) => provider.boot());
        this.phase = 'booted';
    }
    async startAll() {
        this.assertPhase('booted');
        await this.runPhase('starting', 'started', (provider) => provider.start());
        this.phase = 'started';
    }
    async readyAll() {
        this.assertPhase('started');
        await this.runPhase('readying', 'ready', (provider) => provider.ready());
        this.phase = 'ready';
    }
    shutdown() {
        this.shutdownPromise ??= this.shutdownAll();
        return this.shutdownPromise;
    }
    async runPhase(runningState, completedState, run) {
        for (const entry of this.providers) {
            if (entry.state === 'shutdown') {
                continue;
            }
            entry.state = runningState;
            try {
                await run(entry.provider);
                entry.state = completedState;
            }
            catch (error) {
                entry.state = 'failed';
                this.phase = 'failed';
                await this.shutdownAfterFailure(error);
                throw error;
            }
        }
    }

    }
    async shutdownAfterFailure(startupError) {
        try {
            await this.shutdown();
        }
        catch (shutdownError) {
            throw new AggregateError([startupError, shutdownError], 'Provider startup and shutdown both failed.', { cause: shutdownError });
        }
    }
    async shutdownAll() {
        const errors = [];
        this.phase = 'shutting-down';
        for (const entry of [...this.providers].reverse()) {
            if (entry.state === 'new' || entry.state === 'shutdown') {
                continue;
            }
            entry.state = 'shutting-down';
            try {
                await entry.provider.shutdown();
                entry.state = 'shutdown';
            }
            catch (error) {
                entry.state = 'failed';
                errors.push(error);
            }
        }
        this.phase = 'shutdown';
        if (errors.length === 1) {
            throw errors[0];
        }
        if (errors.length > 1) {
            throw new AggregateError(errors, 'Failed to shut down service providers.');
        }
    }
    assertPhase(expected) {
        if (this.phase !== expected) {
            throw new Error(`Cannot run provider phase from state "${this.phase}"; expected "${expected}".`);
        }
    }
